/**
 * Every failure that crosses into Swift, as a thrown error.
 */
public 
enum BasisError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * basis refused or failed the operation; `message` is its own wording.
     */
    case Run(message: String
    )
    /**
     * An argument the binding could not turn into a basis value.
     */
    case InvalidInput(message: String
    )
    /**
     * A foreign callback threw, or could not be reached.
     */
    case Callback(message: String
    )
    /**
     * The binding itself failed: a panicked task or a lost runtime.
     */
    case Internal(message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension BasisError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeBasisError: FfiConverterRustBuffer {
    typealias SwiftType = BasisError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BasisError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Run(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .InvalidInput(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Callback(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Internal(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: BasisError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Run(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .InvalidInput(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Callback(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Internal(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeBasisError_lift(_ buf: RustBuffer) throws -> BasisError {
    return try FfiConverterTypeBasisError.lift(buf)
}

